transformStepData.code:
// Step data transforms
if (stepId === 'select-baseline') {
  return {
    ...data,
    baselineDatasourceId: data.datasourceId,
    baselineTableName: data.name,
    baselineTableType: data.type
  };
}
if (stepId === 'upload-file') {
  return {
    ...data,
    fileId: data.id,
    fileName: data.name,
    fileType: data.type
  };
}
if (stepId === 'field-mapping') {
  return {
    ...data,
    fieldMapping: {
      transactionDate: data.transactionDateField,
      amount: data.amountField,
      counterparty: data.counterpartyField,
      summary: data.summaryField
    }
  };
}
if (stepId === 'match-config') {
  return {
    ...data,
    config: {
      amountTolerance: data.amountTolerance,
      dateTolerance: data.dateTolerance,
      minMatchScore: data.minMatchScore
    }
  };
}
return data;

prepareStepOutput.code:
// Prepare step output
if (stepId === 'execute') {
  return {
    ...data,
    executionId: data.id,
    status: data.status,
    progress: data.progress,
    logs: data.logs
  };
}
if (stepId === 'result') {
  return {
    ...data,
    taskId: data.taskId,
    summary: data.summary,
    matches: data.matches,
    differences: data.differences,
    unmatched: data.unmatched
  };
}
return data;

validateStepData.code:
// Validate step data
const errors = [];
if (stepId === 'select-baseline') {
  if (!data.datasourceId) errors.push('Please select a baseline');
}
if (stepId === 'upload-file') {
  if (!data.id) errors.push('Please upload a reconciliation file');
}
if (stepId === 'field-mapping') {
  if (!data.transactionDateField) errors.push('Please select the transaction date column');
  if (!data.amountField) errors.push('Please select the amount column');
}
if (stepId === 'match-config') {
  if (data.amountTolerance < 0) errors.push('Amount tolerance cannot be negative');
  if (data.dateTolerance < 0) errors.push('Date tolerance cannot be negative');
  if (data.minMatchScore < 0 || data.minMatchScore > 100) errors.push('Minimum match score must be between 0 and 100');
}
return { valid: errors.length === 0, errors };
